SELECT q.id, q.title, SUBSTRING(q.content, 1, 120) AS summary, q.answer_count AS answerCount, q.view_count AS viewCount, q.like_count AS likeCount, q.created_at AS createdAt FROM qa_question q WHERE q.delete_flag = 0 AND q.status = 1 AND (q.title LIKE CONCAT('%', #{query}, '%') OR q.content LIKE CONCAT('%', #{query}, '%'))
AND q.category_id = #{categoryId}
AND q.topic_id = #{topicId}
AND q.answer_count = 0
ORDER BY
q.created_at DESC, q.id DESC (q.like_count * 3 + q.answer_count * 2 + q.view_count) DESC, q.created_at DESC, q.id DESC
(CASE WHEN q.title LIKE CONCAT('%', #{query}, '%') THEN 10 ELSE 0 END + CASE WHEN q.content LIKE CONCAT('%', #{query}, '%') THEN 3 ELSE 0 END + q.like_count * 2 + q.answer_count + q.view_count * 0.2) DESC, q.created_at DESC, q.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT q.id, q.title, SUBSTRING(q.content, 1, 120) AS summary, q.answer_count AS answerCount, q.view_count AS viewCount, q.like_count AS likeCount, q.created_at AS createdAt FROM qa_question q WHERE q.delete_flag = 0 AND q.status = 1 AND q.id IN
#{id}
AND q.category_id = #{categoryId}
AND q.topic_id = #{topicId}
AND q.answer_count = 0
ORDER BY FIELD(q.id,
#{id}
)
